package main

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

const reactNativeReleaseSigningMarker = "// Configure release signing from app-publisher environment variables"

var releaseSigningKeys = []string{
	"KEYSTORE_FILE",
	"KEYSTORE_PASSWORD",
	"KEY_ALIAS",
	"KEY_PASSWORD",
}

// checkGeneratedReleaseSigning validates the credentials used by the release
// signing configuration generated by app-publisher. Custom Gradle signing is
// left to the project.
func checkGeneratedReleaseSigning(cfg Config) error {
	gradleFile, err := findAppBuildFile(cfg.GradleRoot)
	if err != nil {
		return err
	}
	contents, err := os.ReadFile(gradleFile)
	if err != nil {
		return fmt.Errorf("could not inspect Gradle signing configuration %s: %w", gradleFile, err)
	}
	if !strings.Contains(string(contents), kotlinReleaseSigningMarker) &&
		!strings.Contains(string(contents), reactNativeReleaseSigningMarker) {
		return nil
	}

	propertiesPath := filepath.Join(cfg.GradleRoot, "local.properties")
	properties, err := readReleaseSigningProperties(propertiesPath)
	if err != nil {
		return err
	}

	values := make(map[string]string, len(releaseSigningKeys))
	for _, key := range releaseSigningKeys {
		values[key] = strings.TrimSpace(os.Getenv(key))
		if values[key] == "" {
			values[key] = strings.TrimSpace(properties[key])
		}
	}

	var missing []string
	for _, key := range releaseSigningKeys {
		if values[key] == "" {
			missing = append(missing, key)
		}
	}
	if len(missing) > 0 {
		return fmt.Errorf("release signing credentials are missing before the release build\n  Missing: %s\n  Add them to %s or set them as environment variables. No build was started, and deploy did not change versionCode",
			strings.Join(missing, ", "), propertiesPath)
	}

	keystorePath := values["KEYSTORE_FILE"]
	if !filepath.IsAbs(keystorePath) {
		keystorePath = filepath.Join(cfg.GradleRoot, "app", filepath.FromSlash(keystorePath))
	}
	keystoreInfo, err := os.Stat(keystorePath)
	if err != nil {
		if os.IsNotExist(err) {
			return fmt.Errorf("release keystore from KEYSTORE_FILE was not found at %s\n  Check the value in %s or the environment. No versionCode was changed and no build was started",
				keystorePath, propertiesPath)
		}
		return fmt.Errorf("could not access release keystore at %s: %w", keystorePath, err)
	}
	if !keystoreInfo.Mode().IsRegular() {
		return fmt.Errorf("KEYSTORE_FILE does not point to a file: %s\n  Check the value in %s or the environment. No versionCode was changed and no build was started",
			keystorePath, propertiesPath)
	}

	return nil
}

func readReleaseSigningProperties(path string) (map[string]string, error) {
	contents, err := os.ReadFile(path)
	if err != nil {
		if os.IsNotExist(err) {
			return map[string]string{}, nil
		}
		return nil, fmt.Errorf("could not read signing properties from %s: %w", path, err)
	}

	properties := make(map[string]string, len(releaseSigningKeys))
	for _, line := range strings.Split(string(contents), "\n") {
		line = strings.TrimSuffix(line, "\r")
		trimmed := strings.TrimSpace(line)
		if trimmed == "" || strings.HasPrefix(trimmed, "#") || strings.HasPrefix(trimmed, "!") {
			continue
		}

		separator := -1
		escaped := false
		for i := 0; i < len(line); i++ {
			if escaped {
				escaped = false
				continue
			}
			if line[i] == '\\' {
				escaped = true
				continue
			}
			if line[i] == '=' || line[i] == ':' || line[i] == ' ' || line[i] == '\t' || line[i] == '\f' {
				separator = i
				break
			}
		}

		key := line
		value := ""
		if separator >= 0 {
			key = line[:separator]
			remainder := line[separator:]
			for len(remainder) > 0 && (remainder[0] == ' ' || remainder[0] == '\t' || remainder[0] == '\f') {
				remainder = remainder[1:]
			}
			if len(remainder) > 0 && (remainder[0] == '=' || remainder[0] == ':') {
				remainder = remainder[1:]
			}
			value = strings.TrimSpace(remainder)
		}
		properties[strings.TrimSpace(key)] = value
	}
	return properties, nil
}
